import { Device, DeviceOptions } from '@game-studio/device';

import { gameConfig } from '../models/config-model';
import { useCompanionState } from '../models/companion-state';
import { queryStringParams } from './query-string';

/** The arcade-base device instance */
export let device: DeviceEx;

export class DeviceEx extends Device {
    public static initialise(): void {
        device = new DeviceEx({
            forceType: queryStringParams.isSubGame ? 'mobile' : undefined,
            ignoreInversion: queryStringParams.isSubGame
        });

        device.capGameHeightToRatio();
    }

    public showSessionInfoOverGame = true;
    public sessionClientHeight: number = 0;
    private gameHeightScalarRelativeToWidth: number;

    /** The available height for use (viewport.height - action menu height) */
    public get availableHeight(): number {
        const companionState = useCompanionState();

        if (companionState.mode.value === 'side') {
            return this.viewport.height;
        }

        return this.viewport.height - companionState.menuHeight.value;
    }

    /** The height of the game area when chat is open (device.viewport.width * scalar) */
    public get gameHeightScaledToWidth(): number {
        const scalar = this.gameHeightScalarRelativeToWidth || 1; // Fallback to 1 if the scalar is 0 to avoid returning 0 height
        const desiredHeight = this.viewport.width * scalar;
        return Math.min(desiredHeight, this.availableHeight);
    }

    /** The height of the game area when game-in-game is open */
    public get gameHeightInGameInGameView(): number {
        const companionState = useCompanionState();
        const companionHeight = companionState.gigPanelHeight.value + companionState.menuHeight.value;
        return this.viewport.height - companionHeight;
    }

    public get gameHeightInPrizeLeagueView(): number {
        const companionState = useCompanionState();
        const companionHeight = companionState.prizeLeaguePanelHeight.value + companionState.menuHeight.value;
        return this.viewport.height - companionHeight;
    }

    /**
     * The height of the game area available excluding chat and action menu
     */
    public get gameHeight(): number {
        if (queryStringParams.isSubGame) {
            return gameConfig.maintainHeightRatioAsSubGame ? this.gameHeightScaledToWidth : this.availableHeight;
        }

        const companionState = useCompanionState();
        if (companionState.mode.value === 'bottom' && this.orientation.isPortrait) {
            if (companionState.isChatOpen.value) {
                return this.gameHeightScaledToWidth;
            }

            if (companionState.isGameInGameOpen.value) {
                return this.gameHeightInGameInGameView;
            }

            if (companionState.isPrizeLeagueOpen.value) {
                return this.gameHeightInPrizeLeagueView;
            }
        }
        
        return this.availableHeight;
    }

    /**
     * The width of the game area available excluding chat and action menu
     */
    public get gameWidth(): number {
        const companionState = useCompanionState();
        return companionState.mode.value === 'side' && companionState.isEnabled.value === true ? this.viewport.width - companionState.width.value : this.viewport.width;
    }

    public constructor(options: Partial<DeviceOptions> = {}) {
        super(options);

        this.gameHeightScalarRelativeToWidth = gameConfig.heightRatio ?? 0;
    }

    public capGameHeightToRatio(): void {
        const portraitViewport = {
            width: this.orientation.isPortrait ? this.viewport.width : this.viewport.height,
            height: this.orientation.isPortrait ? this.viewport.height : this.viewport.width
        };

        const portraitWindowHeight = this.orientation.isPortrait ? window.innerHeight : window.innerWidth;

        const scalar = this.gameHeightScalarRelativeToWidth || 1;
        const desiredHeight = portraitViewport.width * scalar;
        const portraitGameHeight = Math.min(desiredHeight, this.availableHeight);

        // Cap the height of the game according to the HeightLimit config option
        const heightPercentage = (portraitGameHeight / portraitViewport.height) * 100;
        const shouldCapHeight = heightPercentage !== 100; // We don't cap the height if it's 100%

        if (heightPercentage > gameConfig.heightLimit && shouldCapHeight) {
            const heightToCheck = (portraitWindowHeight * (gameConfig.heightLimit * 0.01));
            this.gameHeightScalarRelativeToWidth = heightToCheck / portraitViewport.width;
        }
    }
}
